import { Request, Response, NextFunction } from "express";
import { query } from "./db";

// Field redaction map. Fields marked @sensitive in the .bone source are
// stripped before the request body is persisted to audit_log.payload.
const SENSITIVE_FIELDS: Record<string, ReadonlyArray<string>> = {};

// Always-redacted keys regardless of entity. Names are matched case-insensitively.
const ALWAYS_REDACT = new Set(["password", "passwd", "pwd", "secret", "token", "api_key", "apikey", "authorization", "ssn", "card_number", "cvv"]);

function redact(payload: unknown, entityType: string | undefined): unknown {
  if (payload == null || typeof payload !== "object") return payload;
  const entitySet = new Set(entityType ? SENSITIVE_FIELDS[entityType] || [] : []);
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(payload as Record<string, unknown>)) {
    if (ALWAYS_REDACT.has(k.toLowerCase()) || entitySet.has(k)) {
      out[k] = "[REDACTED]";
    } else {
      out[k] = v;
    }
  }
  return out;
}

export function auditLog(action: string, entityType?: string) {
  return async (req: Request, _res: Response, next: NextFunction): Promise<void> => {
    try {
      const auth = (req as any).auth as { actor_id?: string | null } | undefined;
      const actorId = auth?.actor_id ?? null;
      const entityId = req.params.id ?? (req.body as Record<string, unknown>)?.id ?? null;
      const redacted = redact(req.body ?? null, entityType);
      const ipAddress = req.ip ?? null;
      const userAgent = req.headers["user-agent"] ?? null;

      await query(
        `INSERT INTO audit_log
          (actor_id, action, entity_type, entity_id, payload, ip_address, user_agent)
          VALUES ($1, $2, $3, $4, $5, $6, $7)`,
        [actorId, action, entityType ?? null, entityId, JSON.stringify(redacted), ipAddress, userAgent]
      );
    } catch (err) {
      // Audit failures must not block the request — log and continue
      console.error("[audit] Failed to write audit log:", err);
    }
    next();
  };
}

export async function getAuditLog(entityType: string, entityId: string): Promise<any[]> {
  return await query(
    "SELECT * FROM audit_log WHERE entity_type = $1 AND entity_id = $2 ORDER BY created_at DESC LIMIT 100",
    [entityType, entityId]
  );
}
